export function TransitionLink({
  href,
  direction,
  className,
  children,
}: {
  href: string
  direction: 'forward' | 'back'
  className?: string
  children: ReactNode
}) {
  const navigate = useViewTransitionNavigation()

  return (
    <Link
      href={href}
      className={className}
      onNavigate={(event) => {
        event.preventDefault()
        navigate(href, direction)
      }}
    >
      {children}
    </Link>
  )
}
